{"command":"$ErrorActionPreference='Stop'
$settings = 'C:\WeGameApps\rail_apps\OasisEraEditor(2001776)\ShadowTrackerExtra\Saved\Config\WindowsUGCEditor\UGCSettings.ini'
$root = 'C:\WeGameApps\rail_apps\OasisEraEditor(2001776)\ShadowTrackerExtra\UGCProjects'
$lines = [System.IO.File]::ReadAllLines($settings, [System.Text.Encoding]::UTF8)
$matches = for ($i = 0; $i -lt $lines.Count; $i++) {
    $line = $lines[$i]
    $assetPath = $null
    if ($line -match 'UGCProjects/Douluo/ExtendResource/([^=]+?)(?:_UploadSourceMd5)?=') {
        $assetPath = 'Douluo/ExtendResource/' + $matches[1]
    } elseif ($line -match '^(Douluo/ExtendResource/[^=]+)=') {
        $assetPath = $matches[1]
    }
    if ($assetPath) {
        $local = Join-Path $root ($assetPath -replace '/', '\')
        [pscustomobject]@{ LineNumber = $i + 1; Line = $line; AssetPath = $assetPath; Exists = (Test-Path -LiteralPath $local) }
    }
}
$matches | Group-Object { ($_.AssetPath -split '/')[2] } | Sort-Object Name | ForEach-Object {
    $missing = ($_.Group | Where-Object { -not $_.Exists }).Count
    $exists = ($_.Group | Where-Object { $_.Exists }).Count
    [pscustomobject]@{ Resource=$_.Name; Total=$_.Count; Exists=$exists; Missing=$missing }
} | Format-Table -AutoSize
"TOTAL_MATCHES=$($matches.Count)"
"TOTAL_MISSING=$(($matches | Where-Object { -not $_.Exists }).Count)"","timeout_ms":10000}

{"command":"$ErrorActionPreference='Stop'
$settings = 'C:\WeGameApps\rail_apps\OasisEraEditor(2001776)\ShadowTrackerExtra\Saved\Config\WindowsUGCEditor\UGCSettings.ini'
$root = 'C:\WeGameApps\rail_apps\OasisEraEditor(2001776)\ShadowTrackerExtra\UGCProjects'
$backup = "$settings.bak_stale_extendresource_cleanup_$(Get-Date -Format 'yyyyMMdd_HHmmss')"
Copy-Item -LiteralPath $settings -Destination $backup
$lines = [System.IO.File]::ReadAllLines($settings, [System.Text.Encoding]::UTF8)
$removed = 0
$kept = New-Object System.Collections.Generic.List[string]
foreach ($line in $lines) {
    $assetPath = $null
    if ($line -match 'UGCProjects/Douluo/ExtendResource/([^=]+?)(?:_UploadSourceMd5)?=') {
        $assetPath = 'Douluo/ExtendResource/' + $matches[1]
    } elseif ($line -match '^(Douluo/ExtendResource/[^=]+)=') {
        $assetPath = $matches[1]
    }

    if ($assetPath) {
        $local = Join-Path $root ($assetPath -replace '/', '\')
        if (-not (Test-Path -LiteralPath $local)) {
            $removed++
            continue
        }
    }
    $kept.Add($line)
}
[System.IO.File]::WriteAllLines($settings, $kept, [System.Text.Encoding]::UTF8)
"BACKUP=$backup"
"REMOVED=$removed"
"TOTAL_BEFORE=$($lines.Count)"
"TOTAL_AFTER=$($kept.Count)"","timeout_ms":10000}

