$projectRoot = Join-Path $base 'UGCProjects'
$jumpDirs = Get-ChildItem -LiteralPath $projectRoot -Directory -Recurse -Force -ErrorAction SilentlyContinue | Where-Object { $_.Name -eq 'JUMP' -and $_.FullName -match '\\ExtendResource\\JUMP$' }
foreach ($dir in $jumpDirs) {
    $resolved = [System.IO.Path]::GetFullPath($dir.FullName)
    $allowed = [System.IO.Path]::GetFullPath($projectRoot)
    if (-not $resolved.StartsWith($allowed, [System.StringComparison]::OrdinalIgnoreCase)) { throw "Unsafe path: $resolved" }
    $relative = $resolved.Substring($allowed.Length).TrimStart('\')
    $dest = Join-Path $backupRoot (Join-Path 'UGCProjects' $relative)
    New-Item -ItemType Directory -Path (Split-Path -Parent $dest) -Force | Out-Null
    Move-Item -LiteralPath $resolved -Destination $dest
}

# Remove all ExtendResource/JUMP records in the active config files, keep backups outside Config.
$configDir = Join-Path $base 'Saved\Config\WindowsUGCEditor'
$activeFiles = @('UGCSettings.ini','EditorPerProjectUserSettings.ini') | ForEach-Object { Join-Path $configDir $_ }
foreach ($file in $activeFiles) {
    if (Test-Path -LiteralPath $file) {
        Copy-Item -LiteralPath $file -Destination (Join-Path $backupRoot (Split-Path -Leaf $file))
        $lines = [System.IO.File]::ReadAllLines($file, [System.Text.Encoding]::UTF8)
        $kept = $lines | Where-Object { $_ -notmatch '(^|UGCProjects/|/)\w+/?ExtendResource/JUMP/' -and $_ -notmatch '\\ExtendResource\\JUMP\\' }
        [System.IO.File]::WriteAllLines($file, $kept, [System.Text.Encoding]::UTF8)
        "CLEANED $file REMOVED=$($lines.Count - $kept.Count)"
    }
}

# Move previous .ini backup files out of Config too, so they cannot be mistaken for active config by any file scan.
$oldBackups = Get-ChildItem -LiteralPath $configDir -Force -File | Where-Object { $_.Name -like 'UGCSettings.ini.bak*' }
foreach ($file in $oldBackups) {
    Move-Item -LiteralPath $file.FullName -Destination (Join-Path $backupRoot $file.Name)
}

"BACKUP_ROOT=$backupRoot"
"MOVED_JUMP_DIRS=$($jumpDirs.Count)"
"MOVED_OLD_BACKUPS=$($oldBackups.Count)"","timeout_ms":20000}

